import{_ as a,o as r,c as e,ag as d}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"关于建议驿站","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),o={name:"about.md"};function l(i,t,n,h,s,u){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="关于建议驿站" tabindex="-1">关于建议驿站 <a class="header-anchor" href="#关于建议驿站" aria-label="Permalink to &quot;关于建议驿站&quot;">​</a></h1><p>**建议驿站（SageRelay）**是一个非官方的科普汇编站：把国家权威部门与官方指定机构发布的指南、标准、数据与查询服务，附上出处，一站站递给需要的人。我们不做任何自创的健康论断——<strong>你在这里看到的每个结论，都能点进原文核对</strong>。</p><h2 id="站上有什么-四种内容形态-工具" tabindex="-1">站上有什么（四种内容形态 + 工具） <a class="header-anchor" href="#站上有什么-四种内容形态-工具" aria-label="Permalink to &quot;站上有什么（四种内容形态 + 工具）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>是什么</th><th>数量</th></tr></thead><tbody><tr><td><strong>词条</strong></td><td>权威指南的速览卡 + 行动清单（买/做/吃/动/测）+ 逐条页码出处</td><td>19 篇</td></tr><tr><td><strong>数据页</strong></td><td>官方统计与工具数据的表格化呈现（不写行动清单）</td><td>3 篇</td></tr><tr><td><strong>国标科普</strong></td><td>消费品国家标准解读（营养标签、食品标签）</td><td>4 篇</td></tr><tr><td><strong>查询页</strong></td><td>官方查询服务导航：化妆品/药品/机构/医师/保健食品/SC/医保</td><td>6 篇</td></tr><tr><td>工具</td><td><a href="/SageRelay/find.html">官方怎么说检索</a> · <a href="/SageRelay/assist.html">家庭管家</a> · <a href="https://yshuai.github.io/SageRelay/corpus.json" target="_blank" rel="noreferrer">AI 语料 JSON</a> · <a href="https://yshuai.github.io/SageRelay/rss.xml" target="_blank" rel="noreferrer">RSS</a></td><td>—</td></tr></tbody></table><h2 id="本站是什么、不是什么" tabindex="-1">本站是什么、不是什么 <a class="header-anchor" href="#本站是什么、不是什么" aria-label="Permalink to &quot;本站是什么、不是什么&quot;">​</a></h2><p><strong>是：</strong></p><ul><li>权威文件的汇编与整理：原文引用 + 地图式/行动式导读 + 逐条出处链接；</li><li>可溯源的知识库：发布机构、版本、印发时间、原文链接，官方 PDF 镜像托管；</li><li>版本受控的档案：指南出新版，旧版归档并注明&quot;已被何年版替代&quot;，永不静默过期。</li></ul><p><strong>不是：</strong></p><ul><li>❌ 官方机构——本站与任何政府部门无关，页面信息一切以原文为准；</li><li>❌ 医疗服务——本站内容不构成诊疗建议，疾病诊疗请遵医嘱；</li><li>❌ AI 咨询师——检索页与家庭管家只做<strong>定位与整理</strong>，不生成个性化健康建议（<a href="/SageRelay/project/adr/0012-ai-agent-roadmap.html">AI 三层路线</a>）；</li><li>❌ 带货号——永不推荐具体商业品牌，没有软文与广告。</li></ul><h2 id="内容来源-三级白名单" tabindex="-1">内容来源（三级白名单） <a class="header-anchor" href="#内容来源-三级白名单" aria-label="Permalink to &quot;内容来源（三级白名单）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>机构</th><th>说明</th></tr></thead><tbody><tr><td>一级</td><td>国务院部委及直属机构，及其运行的政务服务平台（卫健委、疾控局、药监局、标准委、市场监管总局、医保局、国家医保服务平台等）</td><td>政府公文属公共领域</td></tr><tr><td>二级</td><td>官方指定专业机构（中国营养学会、中国疾控中心、中国消费者协会）</td><td>展示时标注来源级别</td></tr><tr><td>三级</td><td>权威医疗机构官方科普与经资质认证的医生科普（规划中，后置启用）</td><td>只链接摘要、不整篇转载，资质可核</td></tr></tbody></table><p>白名单之外的来源（商业健康媒体、自媒体等）一律不收录。</p><h2 id="更新与纠错" tabindex="-1">更新与纠错 <a class="header-anchor" href="#更新与纠错" aria-label="Permalink to &quot;更新与纠错&quot;">​</a></h2><ul><li>每半年对全库做一次版本核查；指南出新版，旧版归档（GB 28050/GB 7718 的 2025 新版动态已按此执行）。</li><li>发现错漏欢迎纠错：<strong>纠错必须附权威来源链接</strong>（白名单内机构发布的原文），否则不受理。</li></ul><h2 id="授权" tabindex="-1">授权 <a class="header-anchor" href="#授权" aria-label="Permalink to &quot;授权&quot;">​</a></h2><p>政府公文与国家标准属公共领域，注明发布机构即可使用；本站自产内容（导读、行动清单、结构化整理）以 <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/deed.zh" target="_blank" rel="noreferrer">CC BY-NC-SA 4.0</a> 授权——署名、非商业、相同方式共享。</p>',16)])])}const c=a(o,[["render",l]]);export{b as __pageData,c as default};
